function Component({ config = {} }) {
  const [selectedColor, setSelectedColor] = React.useState(0);
  const [quantity, setQuantity] = React.useState(1);
  const [activeImage, setActiveImage] = React.useState(0);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const productBrand = config?.productBrand || 'Bang & Olufsen';
  const productTitle = config?.productTitle || 'Beoplay H95';
  const productSubtitle = config?.productSubtitle || 'Premium Wireless Headphones';
  const productPrice = config?.productPrice || '$899.00';
  const originalPrice = config?.originalPrice || '';
  const productDescription = config?.productDescription || 'Experience the pinnacle of audio craftsmanship.';

  const features = [
    { value: config?.feature1 || 'Adaptive ANC', detail: config?.feature1Detail || 'Intelligent noise cancellation' },
    { value: config?.feature2 || '50 Hours', detail: config?.feature2Detail || 'Battery life' },
    { value: config?.feature3 || '40mm Drivers', detail: config?.feature3Detail || 'Titanium drivers' }
  ];

  const colors = [
    { color: config?.color1 || '#1C1917', name: config?.color1Name || 'Black Anthracite' },
    { color: config?.color2 || '#D6D3D1', name: config?.color2Name || 'Grey Mist' },
    { color: config?.color3 || '#92400E', name: config?.color3Name || 'Chestnut' }
  ];

  const backgroundColor = config?.backgroundColor || '#FAFAF9';
  const heroBackground = config?.heroBackground || '#F5F5F4';
  const titleColor = config?.titleColor || '#1C1917';
  const textColor = config?.textColor || '#57534E';
  const accentColor = config?.accentColor || '#1C1917';
  const borderColor = config?.borderColor || '#E7E5E4';

  const imageCount = 4;

  return (
    <div
      className="product-fullwidth-hero"
      style={{
        backgroundColor,
        minHeight: '100vh'
      }}
    >
      {/* Hero Section */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: '1.2fr 1fr',
          minHeight: '85vh'
        }}
      >
        {/* Left: Large Product Image */}
        <div
          style={{
            backgroundColor: heroBackground,
            position: 'relative',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: '60px'
          }}
        >
          {/* Brand Badge */}
          <div
            style={{
              position: 'absolute',
              top: '40px',
              left: '40px',
              fontSize: '12px',
              fontWeight: '600',
              letterSpacing: '0.15em',
              color: textColor,
              textTransform: 'uppercase'
            }}
          >
            {productBrand}
          </div>

          {/* Product Placeholder */}
          <div
            style={{
              width: '80%',
              maxWidth: '500px',
              aspectRatio: '1',
              position: 'relative'
            }}
          >
            {/* Headphone shape placeholder */}
            <div
              style={{
                width: '100%',
                height: '100%',
                borderRadius: '50%',
                background: `radial-gradient(circle at 30% 30%, ${colors[selectedColor].color}40 0%, ${colors[selectedColor].color} 100%)`,
                boxShadow: '0 40px 80px rgba(0,0,0,0.15)',
                position: 'relative'
              }}
            >
              {/* Inner detail */}
              <div
                style={{
                  position: 'absolute',
                  top: '20%',
                  left: '20%',
                  right: '20%',
                  bottom: '20%',
                  borderRadius: '50%',
                  border: `3px solid ${backgroundColor}30`
                }}
              />
            </div>
          </div>

          {/* Image Navigation Dots */}
          <div
            style={{
              position: 'absolute',
              bottom: '40px',
              left: '50%',
              transform: 'translateX(-50%)',
              display: 'flex',
              gap: '12px'
            }}
          >
            {Array.from({ length: imageCount }, (_, i) => (
              <button
                key={i}
                onClick={() => setActiveImage(i)}
                style={{
                  width: activeImage === i ? '24px' : '8px',
                  height: '8px',
                  borderRadius: '4px',
                  backgroundColor: activeImage === i ? titleColor : borderColor,
                  border: 'none',
                  cursor: 'pointer',
                  transition: prefersReducedMotion ? 'none' : 'all 300ms ease-out'
                }}
                aria-label={`View image ${i + 1}`}
              />
            ))}
          </div>

          {/* Zoom Button */}
          <button
            style={{
              position: 'absolute',
              bottom: '40px',
              right: '40px',
              width: '48px',
              height: '48px',
              borderRadius: '50%',
              backgroundColor: backgroundColor,
              border: 'none',
              boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
              cursor: 'pointer',
              fontSize: '18px',
              color: textColor
            }}
            aria-label="Zoom image"
          >
            ⤢
          </button>
        </div>

        {/* Right: Product Info */}
        <div
          style={{
            padding: '60px 60px 60px 48px',
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'center'
          }}
        >
          {/* Subtitle */}
          <p
            style={{
              fontSize: '13px',
              fontWeight: '500',
              letterSpacing: '0.1em',
              color: textColor,
              textTransform: 'uppercase',
              margin: '0 0 12px 0'
            }}
          >
            {productSubtitle}
          </p>

          {/* Title */}
          <h1
            style={{
              fontSize: '48px',
              fontWeight: '300',
              color: titleColor,
              margin: '0 0 24px 0',
              lineHeight: '1.1',
              letterSpacing: '-0.02em'
            }}
          >
            {productTitle}
          </h1>

          {/* Price */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '16px',
              marginBottom: '24px'
            }}
          >
            <span style={{ fontSize: '28px', fontWeight: '400', color: titleColor }}>
              {productPrice}
            </span>
            {originalPrice && (
              <span style={{ fontSize: '18px', color: textColor, textDecoration: 'line-through' }}>
                {originalPrice}
              </span>
            )}
          </div>

          {/* Description */}
          <p
            style={{
              fontSize: '16px',
              color: textColor,
              lineHeight: '1.7',
              margin: '0 0 32px 0',
              maxWidth: '480px'
            }}
          >
            {productDescription}
          </p>

          {/* Features */}
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(3, 1fr)',
              gap: '24px',
              marginBottom: '40px',
              paddingBottom: '40px',
              borderBottom: `1px solid ${borderColor}`
            }}
          >
            {features.map((feature, index) => (
              <div key={index}>
                <div style={{ fontSize: '20px', fontWeight: '500', color: titleColor, marginBottom: '4px' }}>
                  {feature.value}
                </div>
                <div style={{ fontSize: '13px', color: textColor }}>
                  {feature.detail}
                </div>
              </div>
            ))}
          </div>

          {/* Color Selection */}
          <div style={{ marginBottom: '32px' }}>
            <div style={{ fontSize: '14px', color: titleColor, marginBottom: '16px' }}>
              Color: <span style={{ fontWeight: '500' }}>{colors[selectedColor].name}</span>
            </div>
            <div style={{ display: 'flex', gap: '12px' }}>
              {colors.map((c, index) => (
                <button
                  key={index}
                  onClick={() => setSelectedColor(index)}
                  style={{
                    width: '40px',
                    height: '40px',
                    borderRadius: '50%',
                    backgroundColor: c.color,
                    border: selectedColor === index ? `2px solid ${titleColor}` : '2px solid transparent',
                    outline: selectedColor === index ? `2px solid ${backgroundColor}` : 'none',
                    outlineOffset: '-4px',
                    cursor: 'pointer',
                    transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out'
                  }}
                  aria-label={c.name}
                />
              ))}
            </div>
          </div>

          {/* Quantity */}
          <div style={{ marginBottom: '32px' }}>
            <div style={{ fontSize: '14px', color: titleColor, marginBottom: '12px' }}>Quantity</div>
            <div
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                border: `1px solid ${borderColor}`,
                borderRadius: '8px'
              }}
            >
              <button
                onClick={() => setQuantity(Math.max(1, quantity - 1))}
                style={{
                  width: '48px',
                  height: '48px',
                  border: 'none',
                  backgroundColor: 'transparent',
                  fontSize: '20px',
                  cursor: 'pointer',
                  color: textColor
                }}
              >
                −
              </button>
              <span style={{ width: '48px', textAlign: 'center', fontSize: '16px', color: titleColor, fontWeight: '500' }}>
                {quantity}
              </span>
              <button
                onClick={() => setQuantity(quantity + 1)}
                style={{
                  width: '48px',
                  height: '48px',
                  border: 'none',
                  backgroundColor: 'transparent',
                  fontSize: '20px',
                  cursor: 'pointer',
                  color: textColor
                }}
              >
                +
              </button>
            </div>
          </div>

          {/* Action Buttons */}
          <div style={{ display: 'flex', gap: '16px' }}>
            <button
              style={{
                flex: 1,
                padding: '18px 32px',
                borderRadius: '0',
                backgroundColor: accentColor,
                color: backgroundColor,
                border: 'none',
                fontSize: '14px',
                fontWeight: '500',
                letterSpacing: '0.05em',
                cursor: 'pointer',
                transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out'
              }}
            >
              Add to Cart — {productPrice}
            </button>
            <button
              style={{
                padding: '18px 24px',
                borderRadius: '0',
                backgroundColor: 'transparent',
                color: titleColor,
                border: `1px solid ${borderColor}`,
                fontSize: '16px',
                cursor: 'pointer'
              }}
              aria-label="Add to wishlist"
            >
              ♡
            </button>
          </div>

          {/* Trust Badges */}
          <div
            style={{
              display: 'flex',
              gap: '24px',
              marginTop: '32px',
              paddingTop: '32px',
              borderTop: `1px solid ${borderColor}`
            }}
          >
            {[
              { icon: '🚚', text: 'Free Shipping' },
              { icon: '↩️', text: '30-Day Returns' },
              { icon: '🛡️', text: '2-Year Warranty' }
            ].map((badge, index) => (
              <div key={index} style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <span style={{ fontSize: '16px' }}>{badge.icon}</span>
                <span style={{ fontSize: '13px', color: textColor }}>{badge.text}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

layout-infinitemarquee:
const MANIFEST = {
  "type": "Layout.InfiniteMarquee",
  "description": "Infinite horizontal scrolling marquee with seamless loop",
  "editorElement": {
    "selector": ".infinite-marquee",
    "displayName": "Infinite Marquee",
    "archetype": "container",
    "data": {
      "items": {
        "dataType": "text",
        "displayName": "Items (comma-separated)",
        "defaultValue": "React, Vue, Angular, Svelte, Next.js, Nuxt.js, Gatsby, Remix",
        "group": "Content"
      },
      "speed": {
        "dataType": "select",
        "displayName": "Scroll Speed",
        "defaultValue": "normal",
        "options": ["slow", "normal", "fast", "very-fast"],
        "group": "Animation",
        "description": "slow=60s, normal=40s, fast=25s, very-fast=15s"
      },
      "direction": {
        "dataType": "select",
        "displayName": "Direction",
        "defaultValue": "left",
        "options": ["left", "right"],
        "group": "Animation"
      },
      "pauseOnHover": {
        "dataType": "booleanValue",
        "displayName": "Pause On Hover",
        "defaultValue": true,
        "group": "Animation"
      },
      "gap": {
        "dataType": "select",
        "displayName": "Gap Between Items",
        "defaultValue": "48",
        "options": ["24", "32", "40", "48", "64", "80"],
        "group": "Layout"
      },
      "itemPadding": {
        "dataType": "select",
        "displayName": "Item Padding",
        "defaultValue": "16",
        "options": ["12", "16", "20", "24"],
        "group": "Layout"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "itemBackgroundColor": {
        "dataType": "color",
        "displayName": "Item Background",
        "defaultValue": "#F4F4F5",
        "group": "Colors"
      },
      "borderColor": {
        "dataType": "color",
        "displayName": "Border Color",
        "defaultValue": "#E4E4E7",
        "group": "Colors"
      },
      "fontSize": {
        "dataType": "number",
        "displayName": "Font Size (px)",
        "defaultValue": 16,
        "group": "Typography"
      },
      "fontWeight": {
        "dataType": "select",
        "displayName": "Font Weight",
        "defaultValue": "500",
        "options": ["300", "400", "500"],
        "group": "Typography"
      },
      "borderRadius": {
        "dataType": "select",
        "displayName": "Border Radius",
        "defaultValue": "8",
        "options": ["0", "4", "6", "8", "12", "100"],
        "group": "Layout"
      }
    },
    "layout": {
      "resizeDirection": "horizontal",
      "contentResizeDirection": "horizontal"
    }
  }
};

function Component({ config = {} }) {
  const [isPaused, setIsPaused] = React.useState(false);

  // Config values
  const itemsString = config?.items || "React, Vue, Angular, Svelte, Next.js, Nuxt.js, Gatsby, Remix";
  const items = itemsString.split(',').map(item => item.trim()).filter(Boolean);
  const speed = config?.speed || "normal";
  const direction = config?.direction || "left";
  const pauseOnHover = config?.pauseOnHover !== false;
  const gap = parseInt(config?.gap || "48");
  const itemPadding = parseInt(config?.itemPadding || "16");
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const textColor = config?.textColor || "#18181B";
  const itemBackgroundColor = config?.itemBackgroundColor || "#F4F4F5";
  const borderColor = config?.borderColor || "#E4E4E7";
  const fontSize = config?.fontSize || 16;
  const fontWeight = config?.fontWeight || "500";
  const borderRadius = parseInt(config?.borderRadius || "8");

  const prefersReducedMotion = typeof window !== 'undefined' 
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches 
    : false;

  // Speed mapping
  const speedMap = {
    'slow': '60s',
    'normal': '40s',
    'fast': '25s',
    'very-fast': '15s'
  };
  const animationDuration = speedMap[speed] || '40s';

  // Double the items for seamless loop
  const doubledItems = [...items, ...items];

  const containerStyle = {
    width: '100%',
    backgroundColor: backgroundColor,
    overflow: 'hidden',
    padding: '24px 0',
    position: 'relative'
  };

  const trackStyle = {
    display: 'flex',
    gap: `${gap}px`,
    width: 'fit-content',
    animation: prefersReducedMotion 
      ? 'none' 
      : `marquee-${direction} ${animationDuration} linear infinite`,
    animationPlayState: (pauseOnHover && isPaused) ? 'paused' : 'running'
  };

  const itemStyle = {
    flex: '0 0 auto',
    padding: `${itemPadding}px ${itemPadding * 1.5}px`,
    backgroundColor: itemBackgroundColor,
    color: textColor,
    borderRadius: `${borderRadius}px`,
    border: `1px solid ${borderColor}`,
    fontSize: `${fontSize}px`,
    fontWeight: fontWeight,
    whiteSpace: 'nowrap',
    userSelect: 'none'
  };

  const animationKeyframes = `
    @keyframes marquee-left {
      0% {
        transform: translateX(0);
      }
      100% {
        transform: translateX(calc(-50% - ${gap / 2}px));
      }
    }

    @keyframes marquee-right {
      0% {
        transform: translateX(calc(-50% - ${gap / 2}px));
      }
      100% {
        transform: translateX(0);
      }
    }
  `;

  return (
    <div 
      className="infinite-marquee"
      style={containerStyle}
      onMouseEnter={() => pauseOnHover && setIsPaused(true)}
      onMouseLeave={() => pauseOnHover && setIsPaused(false)}
      role="marquee"
      aria-label="Scrolling content"
    >
      <style>{animationKeyframes}</style>

      <div style={trackStyle}>
        {doubledItems.map((item, index) => (
          <div key={index} style={itemStyle}>
            {item}
          </div>
        ))}
      </div>
    </div>
  );
}

