  const heroImage = config?.heroImage || "https://images.unsplash.com/photo-1618005198919-d3d4b5a92ead?w=1200&q=80";
  const textBackgroundColor = config?.textBackgroundColor || "#FAFAFA";
  const headlineColor = config?.headlineColor || "#171717";
  const descriptionColor = config?.descriptionColor || "#737373";
  const eyebrowColor = config?.eyebrowColor || "#737373";
  const ctaBackgroundColor = config?.ctaBackgroundColor || "#000000";
  const ctaTextColor = config?.ctaTextColor || "#FFFFFF";
  const headlineFontSize = parseInt(config?.headlineFontSize || "80");
  const headlineFontWeight = config?.headlineFontWeight || "700";
  const layoutDirection = config?.layoutDirection || "text-left";
  const animationDuration = parseInt(config?.animationDuration || "500");
  const enableAnimation = config?.enableAnimation !== false;

  const [isVisible, setIsVisible] = React.useState(false);
  const heroRef = React.useRef(null);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  React.useEffect(() => {
    if (!enableAnimation || prefersReducedMotion) {
      setIsVisible(true);
      return;
    }

    const timer = setTimeout(() => {
      setIsVisible(true);
    }, 100);

    return () => clearTimeout(timer);
  }, [enableAnimation, prefersReducedMotion]);

  const shouldAnimate = enableAnimation && !prefersReducedMotion;
  const isTextLeft = layoutDirection === "text-left";

  return (
    <div
      ref={heroRef}
      className="hero-asymmetric-split"
      style={{
        display: 'flex',
        flexDirection: 'row',
        minHeight: '100vh',
        width: '100%',
        overflow: 'hidden'
      }}
    >
      <style>{`
        @media (max-width: 768px) {
          .hero-asymmetric-split {
            flex-direction: column !important;
          }
          .hero-text-area, .hero-image-area {
            width: 100% !important;
            min-height: 50vh !important;
          }
        }
      `}</style>

      {/* Text Content Area */}
      <div
        className="hero-text-area"
        style={{
          width: '50%',
          backgroundColor: textBackgroundColor,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          padding: 'clamp(40px, 6vw, 80px)',
          order: isTextLeft ? 1 : 2,
          opacity: shouldAnimate ? (isVisible ? 1 : 0) : 1,
          transform: shouldAnimate ? (isVisible ? 'translateX(0)' : `translateX(${isTextLeft ? '-40px' : '40px'})`) : 'translateX(0)',
          transition: shouldAnimate ? `opacity ${animationDuration}ms ease-out, transform ${animationDuration}ms ease-out` : 'none'
        }}
      >
        <div style={{ maxWidth: '540px', width: '100%' }}>
          {/* Eyebrow */}
          <div
            style={{
              fontSize: '12px',
              fontWeight: '600',
              color: eyebrowColor,
              letterSpacing: '0.15em',
              textTransform: 'uppercase',
              marginBottom: '24px',
              fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
            }}
          >
            {eyebrow}
          </div>

          {/* Headline */}
          <h1
            style={{
              fontSize: `clamp(${headlineFontSize * 0.45}px, ${headlineFontSize * 0.08}vw + ${headlineFontSize * 0.3}px, ${headlineFontSize}px)`,
              fontWeight: headlineFontWeight,
              color: headlineColor,
              margin: '0 0 32px 0',
              lineHeight: '1.1',
              letterSpacing: '-0.03em',
              fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
            }}
          >
            {headline}
          </h1>

          {/* Description */}
          <p
            style={{
              fontSize: '18px',
              fontWeight: '300',
              color: descriptionColor,
              margin: '0 0 40px 0',
              lineHeight: '1.7',
              fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
            }}
          >
            {description}
          </p>

          {/* CTA Button */}
          <a
            href={ctaLink}
            style={{
              display: 'inline-block',
              padding: '18px 42px',
              fontSize: '15px',
              fontWeight: '600',
              color: ctaTextColor,
              backgroundColor: ctaBackgroundColor,
              border: 'none',
              textDecoration: 'none',
              fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
              cursor: 'pointer',
              transition: 'transform 300ms ease-out, opacity 300ms ease-out',
              letterSpacing: '0.02em'
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.transform = 'translateY(-3px)';
              e.currentTarget.style.opacity = '0.9';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'translateY(0)';
              e.currentTarget.style.opacity = '1';
            }}
          >
            {ctaText}
          </a>
        </div>
      </div>

      {/* Image Area */}
      <div
        className="hero-image-area"
        style={{
          width: '50%',
          position: 'relative',
          overflow: 'hidden',
          order: isTextLeft ? 2 : 1,
          opacity: shouldAnimate ? (isVisible ? 1 : 0) : 1,
          transform: shouldAnimate ? (isVisible ? 'translateX(0)' : `translateX(${isTextLeft ? '40px' : '-40px'})`) : 'translateX(0)',
          transition: shouldAnimate ? `opacity ${animationDuration}ms ease-out ${animationDuration * 0.2}ms, transform ${animationDuration}ms ease-out ${animationDuration * 0.2}ms` : 'none'
        }}
      >
        <div
          style={{
            width: '100%',
            height: '100%',
            overflow: 'hidden'
          }}
          onMouseEnter={(e) => {
            const img = e.currentTarget.querySelector('img');
            if (img) img.style.transform = 'scale(1.05)';
          }}
          onMouseLeave={(e) => {
            const img = e.currentTarget.querySelector('img');
            if (img) img.style.transform = 'scale(1)';
          }}
        >
          <img
            src={heroImage}
            alt="Hero"
            style={{
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              transition: 'transform 600ms ease-out'
            }}
          />
        </div>
      </div>
    </div>
  );
}

