  const imageUrlsString = config?.imageUrls || "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=200,https://images.unsplash.com/photo-1607434472257-d9f8e57a643d?w=200,https://images.unsplash.com/photo-1618556450994-a6a128ef0d9d?w=200,https://images.unsplash.com/photo-1618005198919-d3d4b5a92ead?w=200,https://images.unsplash.com/photo-1611689342806-0863700ce1e4?w=200,https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?w=200";
  const baseVelocity = parseFloat(config?.baseVelocity || "2");
  const repeatCount = parseInt(config?.repeatCount || "2");
  const slowdownOnHover = config?.slowdownOnHover !== false;
  const slowdownFactor = parseFloat(config?.slowdownFactor || "0.4");
  const enableDrag = config?.enableDrag !== false;
  const dragSensitivity = parseFloat(config?.dragSensitivity || "0.1");
  const imageSize = parseInt(config?.imageSize || "56");
  const imageGap = parseInt(config?.imageGap || "16");
  const hoverScale = parseFloat(config?.hoverScale || "1.5");
  const backgroundColor = config?.backgroundColor || "#F8F9FA";
  const imageBorderColor = config?.imageBorderColor || "#E9ECEF";
  const pathStrokeColor = config?.pathStrokeColor || "#CED4DA";
  const showDebugPath = config?.showDebugPath || false;

  const containerRef = React.useRef(null);
  const pathRef = React.useRef(null);
  const svgRef = React.useRef(null);
  const animationRef = React.useRef(null);
  const offsetRef = React.useRef(0);
  const velocityRef = React.useRef(baseVelocity);
  const targetVelocityRef = React.useRef(baseVelocity);
  const isHoveringRef = React.useRef(false);
  const isDraggingRef = React.useRef(false);
  const dragStartRef = React.useRef({ x: 0, offset: 0 });
  const imageElementsRef = React.useRef([]);

  const [pathLength, setPathLength] = React.useState(0);
  const [hoveredIndex, setHoveredIndex] = React.useState(null);
  const [dimensions, setDimensions] = React.useState({ width: 0, height: 0 });

  const imageUrls = imageUrlsString.split(',').map(url => url.trim());
  const allImages = Array(repeatCount).fill(imageUrls).flat();

  const prefersReducedMotion = typeof window !== 'undefined' 
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches 
    : false;

  // Path presets
  const pathPresets = {
    wave: "M 50 200 Q 200 100, 350 200 T 650 200 T 950 200",
    curve: "M 50 250 C 200 50, 400 350, 550 200 C 700 50, 800 300, 950 150",
    spiral: "M 500 200 Q 600 100, 700 200 Q 650 300, 500 280 Q 350 260, 380 200 Q 400 150, 500 160",
    loop: "M 100 200 Q 250 50, 400 200 Q 550 350, 700 200 Q 850 50, 900 200",
    zigzag: "M 50 150 L 200 250 L 350 150 L 500 250 L 650 150 L 800 250 L 950 150"
  };

  const currentPath = pathPresets[pathPreset] || pathPresets.wave;

  // Get container dimensions
  React.useEffect(() => {
    const updateDimensions = () => {
      if (containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        setDimensions({ width: rect.width, height: rect.height });
      }
    };

    updateDimensions();
    window.addEventListener('resize', updateDimensions);
    return () => window.removeEventListener('resize', updateDimensions);
  }, []);

  // Calculate path length
  React.useEffect(() => {
    if (pathRef.current) {
      const length = pathRef.current.getTotalLength();
      setPathLength(length);
    }
  }, [currentPath]);

  // Update velocity when base changes
  React.useEffect(() => {
    targetVelocityRef.current = baseVelocity;
    velocityRef.current = baseVelocity;
  }, [baseVelocity]);

  // Animation loop
  React.useEffect(() => {
    if (!pathLength || !dimensions.width || prefersReducedMotion) return;

    const animate = () => {
      velocityRef.current += (targetVelocityRef.current - velocityRef.current) * 0.1;

      if (!isDraggingRef.current) {
        offsetRef.current += velocityRef.current;
        if (offsetRef.current > pathLength) {
          offsetRef.current = offsetRef.current % pathLength;
        }
      }

      updatePositions();
      animationRef.current = requestAnimationFrame(animate);
    };

    animationRef.current = requestAnimationFrame(animate);

    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [pathLength, dimensions, prefersReducedMotion]);

  const updatePositions = () => {
    if (!pathRef.current || !svgRef.current) return;

    const svgRect = svgRef.current.getBoundingClientRect();
    const scaleX = svgRect.width / 1000;
    const scaleY = svgRect.height / 400;
    const spacing = imageSize + imageGap;

    imageElementsRef.current.forEach((img, index) => {
      if (!img) return;

      const position = (offsetRef.current + index * spacing) % pathLength;
      const point = pathRef.current.getPointAtLength(position);

      const nextPos = (position + 1) % pathLength;
      const nextPoint = pathRef.current.getPointAtLength(nextPos);
      const angle = Math.atan2(nextPoint.y - point.y, nextPoint.x - point.x) * (180 / Math.PI);

      const scaledX = point.x * scaleX;
      const scaledY = point.y * scaleY;

      img.style.left = `${scaledX}px`;
      img.style.top = `${scaledY}px`;
      img.style.transform = `translate(-50%, -50%) rotate(${angle}deg)`;
    });
  };

  const handleMouseEnter = () => {
    if (slowdownOnHover && !isDraggingRef.current) {
      isHoveringRef.current = true;
      targetVelocityRef.current = baseVelocity * slowdownFactor;
    }
  };

  const handleMouseLeave = () => {
    if (slowdownOnHover) {
      isHoveringRef.current = false;
      if (!isDraggingRef.current) {
        targetVelocityRef.current = baseVelocity;
      }
    }
    setHoveredIndex(null);
  };

  const handleMouseDown = (e) => {
    if (!enableDrag) return;
    e.preventDefault();
    isDraggingRef.current = true;
    dragStartRef.current = { 
      x: e.clientX, 
      offset: offsetRef.current 
    };
    targetVelocityRef.current = 0;
  };

  const handleMouseMove = (e) => {
    if (!isDraggingRef.current || !enableDrag) return;
    const deltaX = e.clientX - dragStartRef.current.x;
    offsetRef.current = (dragStartRef.current.offset - deltaX * dragSensitivity * 100 + pathLength * 10) % pathLength;
  };

  const handleMouseUp = () => {
    if (!enableDrag || !isDraggingRef.current) return;
    isDraggingRef.current = false;
    targetVelocityRef.current = isHoveringRef.current ? baseVelocity * slowdownFactor : baseVelocity;
  };

  React.useEffect(() => {
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [enableDrag, dragSensitivity, pathLength]);

  return (
    <div 
      ref={containerRef}
      className="svg-path-marquee"
      style={{
        width: '100%',
        height: '100%',
        minHeight: '400px',
        backgroundColor,
        position: 'relative',
        overflow: 'hidden',
        cursor: enableDrag ? (isDraggingRef.current ? 'grabbing' : 'grab') : 'default',
        userSelect: 'none'
      }}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      onMouseDown={handleMouseDown}
    >
      <svg 
        ref={svgRef}
        viewBox="0 0 1000 400"
        preserveAspectRatio="xMidYMid meet"
        style={{ 
          position: 'absolute', 
          width: '100%', 
          height: '100%',
          pointerEvents: 'none'
        }}
      >
        <path
          ref={pathRef}
          d={currentPath}
          fill="none"
          stroke={showDebugPath ? pathStrokeColor : 'transparent'}
          strokeWidth="3"
          opacity={showDebugPath ? 0.6 : 0}
        />
      </svg>

      {allImages.map((url, index) => (
        <div
          key={index}
          ref={el => imageElementsRef.current[index] = el}
          style={{
            position: 'absolute',
            width: `${imageSize}px`,
            height: `${imageSize}px`,
            borderRadius: '8px',
            overflow: 'hidden',
            border: `1px solid ${imageBorderColor}`,
            backgroundColor: '#FFFFFF',
            boxShadow: hoveredIndex === index ? '0 8px 24px rgba(0,0,0,0.12)' : '0 2px 8px rgba(0,0,0,0.06)',
            pointerEvents: 'auto',
            cursor: 'pointer',
            transition: prefersReducedMotion ? 'none' : 'box-shadow 200ms ease-out',
            transform: hoveredIndex === index ? `translate(-50%, -50%) scale(${hoverScale})` : 'translate(-50%, -50%)',
            zIndex: hoveredIndex === index ? 100 : 1,
            willChange: 'transform'
          }}
          onMouseEnter={(e) => {
            e.stopPropagation();
            if (!prefersReducedMotion) {
              setHoveredIndex(index);
            }
          }}
          onMouseLeave={(e) => {
            e.stopPropagation();
            setHoveredIndex(null);
          }}
        >
          <img
            src={url}
            alt={`Marquee item ${index + 1}`}
            style={{
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              display: 'block',
              userSelect: 'none',
              pointerEvents: 'none'
            }}
            draggable="false"
          />
        </div>
      ))}
    </div>
  );
}

