const MANIFEST = {
  "type": "Hero.TypographyMask",
  "description": "Massive kinetic typography where images play inside the text characters.",
  "editorElement": {
    "selector": ".type-mask",
    "displayName": "Typography Mask Hero",
    "archetype": "container",
    "data": {
      "text": {
        "dataType": "text",
        "displayName": "Display Text",
        "defaultValue": "DESIGN",
        "group": "Content"
      },
      "images": {
        "dataType": "text",
        "displayName": "Image URLs (Comma Sep)",
        "defaultValue": "https://images.unsplash.com/photo-1492633423870-43d1cd2775eb?q=80&w=2070,https://images.unsplash.com/photo-1544967082-d9d25d867d66?q=80&w=2070,https://images.unsplash.com/photo-1516035069371-29a1b244cc32?q=80&w=2000",
        "group": "Content"
      },
      "slideDuration": {
        "dataType": "number",
        "displayName": "Slide Duration (ms)",
        "defaultValue": 4000,
        "group": "Animation"
      },
      "fontScale": {
        "dataType": "number",
        "displayName": "Font Scale (vw)",
        "defaultValue": 25,
        "group": "Typography",
        "description": "Size relative to viewport width"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const [activeIndex, setActiveIndex] = React.useState(0);
  const [nextIndex, setNextIndex] = React.useState(1);
  const [isTransitioning, setIsTransitioning] = React.useState(false);
  const timerRef = React.useRef(null);

  // Safe Config
  const text = (config?.text || 'DESIGN').toUpperCase();
  const rawImages = config?.images || '';
  const images = React.useMemo(() => rawImages.split(',').map(i => i.trim()).filter(Boolean), [rawImages]);
  const duration = parseInt(config?.slideDuration || '4000');
  const fontScale = parseInt(config?.fontScale || '25'); // vw units
  const bg = config?.backgroundColor || '#FFFFFF';

  // Transition Logic
  const nextSlide = React.useCallback(() => {
    if (images.length < 2) return;
    setIsTransitioning(true);

    setTimeout(() => {
      setActiveIndex(prev => (prev + 1) % images.length);
      setNextIndex(prev => (prev + 1) % images.length);
      setIsTransitioning(false);
    }, 1000); // Transition duration matches CSS
  }, [images.length]);

  React.useEffect(() => {
    timerRef.current = setInterval(nextSlide, duration);
    return () => clearInterval(timerRef.current);
  }, [nextSlide, duration]);

  // If no images, show fallback
  if (images.length === 0) return <div style={{ padding: 20 }}>Please add images</div>;

  return (
    <div
      className="type-mask-hero"
      style={{
        width: '100%',
        height: '100%',
        minHeight: '600px',
        backgroundColor: bg,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        position: 'relative',
        overflow: 'hidden',
        userSelect: 'none'
      }}
    >
      {/* Container for the text layers */}
      <div style={{
        position: 'relative',
        width: '100%',
        textAlign: 'center',
        zIndex: 10
      }}>

        {/* Layer 1: The "Next" Image (Fades In) */}
        <h1
          aria-hidden="true"
          style={{
            fontSize: `${fontScale}vw`,
            lineHeight: 0.85,
            fontWeight: 900,
            fontFamily: '-apple-system, BlinkMacSystemFont, "Inter", "Helvetica Neue", sans-serif',
            letterSpacing: '-0.05em',
            margin: 0,
            padding: '20px', // Prevent clip cutoff
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            width: '100%',

            // Masking Magic
            color: 'transparent',
            backgroundImage: `url(${images[nextIndex]})`,
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            WebkitBackgroundClip: 'text',
            backgroundClip: 'text',

            // Animation state
            opacity: isTransitioning ? 1 : 0, 
            transition: 'opacity 1000ms ease-in-out'
          }}
        >
          {text}
        </h1>

        {/* Layer 2: The "Active" Image (Always Visible until swapped) */}
        <h1
          style={{
            fontSize: `${fontScale}vw`,
            lineHeight: 0.85,
            fontWeight: 900,
            fontFamily: '-apple-system, BlinkMacSystemFont, "Inter", "Helvetica Neue", sans-serif',
            letterSpacing: '-0.05em',
            margin: 0,
            padding: '20px',
            position: 'relative', // Relative to hold height

            // Masking Magic
            color: 'transparent',
            backgroundImage: `url(${images[activeIndex]})`,
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            WebkitBackgroundClip: 'text',
            backgroundClip: 'text',

            // This layer stays opaque, the one above fades in over it
            opacity: 1,
            zIndex: 5
          }}
        >
          {text}
        </h1>
      </div>

      {/* Decorative Elements (Corners) */}
      <div style={{ position: 'absolute', top: 30, left: 30, borderTop: '2px solid #000', borderLeft: '2px solid #000', width: 20, height: 20, opacity: 0.2 }}></div>
      <div style={{ position: 'absolute', top: 30, right: 30, borderTop: '2px solid #000', borderRight: '2px solid #000', width: 20, height: 20, opacity: 0.2 }}></div>
      <div style={{ position: 'absolute', bottom: 30, left: 30, borderBottom: '2px solid #000', borderLeft: '2px solid #000', width: 20, height: 20, opacity: 0.2 }}></div>
      <div style={{ position: 'absolute', bottom: 30, right: 30, borderBottom: '2px solid #000', borderRight: '2px solid #000', width: 20, height: 20, opacity: 0.2 }}></div>

      {/* Progress Line */}
      <div style={{
        position: 'absolute',
        bottom: 0,
        left: 0,
        height: '4px',
        backgroundColor: '#000000',
        width: '100%',
        transformOrigin: 'left',
        transform: isTransitioning ? 'scaleX(0)' : 'scaleX(1)',
        transition: isTransitioning ? 'none' : `transform ${duration}ms linear`,
        opacity: 0.1
      }} />
    </div>
  );
}

